solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(BigInt);
function extGcd(a, b) {
  let x0 = 1n, y0 = 0n, x1 = 0n, y1 = 1n;
  while (b !== 0n) {
    const q = a / b;
    [a, b] = [b, a - q * b];
    [x0, x1] = [x1, x0 - q * x1];
    [y0, y1] = [y1, y0 - q * y1];
  }
  return [a, x0, y0];
}
const k = Number(tok[0]);
let r = 0n, m = 1n;
let ok = true;
for (let i = 0; i < k && ok; i++) {
  const r2 = tok[1 + 2 * i], m2 = tok[2 + 2 * i];
  const [g, p] = extGcd(m, m2);
  const diff = r2 - r;
  if (diff % g !== 0n) { ok = false; break; }
  const mod = m2 / g;
  let t = ((diff / g) * p) % mod;
  if (t < 0n) t += mod;
  const newM = (m / g) * m2;
  r = (r + m * t) % newM;
  m = newM;
}
console.log(ok ? r.toString() : '-1');

