import java.util.*;

public class Main {
    static long coef;                                   // Bezout coefficient of the first argument
    static long extGcd(long a, long b) {
        long x0 = 1, x1 = 0;
        while (b != 0) {
            long q = a / b;
            long t = a - q * b; a = b; b = t;
            t = x0 - q * x1; x0 = x1; x1 = t;
        }
        coef = x0;
        return a;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        long r = 0, m = 1;
        for (int i = 0; i < k; i++) {
            long r2 = sc.nextLong(), m2 = sc.nextLong();
            long g = extGcd(m, m2);
            long diff = r2 - r;
            if (diff % g != 0) { System.out.println(-1); return; }
            long mod = m2 / g;
            long t = ((diff / g) % mod) * (coef % mod) % mod;      // each factor is below 10^6 after reduction
            if (t < 0) t += mod;
            long newM = m / g * m2;
            r = (r + m * t) % newM;
            m = newM;
        }
        System.out.println(r);
    }
}

