#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll coef;
ll extGcd(ll a, ll b) {
    ll x0 = 1, x1 = 0;
    while (b != 0) {
        ll q = a / b;
        ll t = a - q * b; a = b; b = t;
        t = x0 - q * x1; x0 = x1; x1 = t;
    }
    coef = x0;
    return a;
}
int main() {
    int k;
    scanf("%d", &k);
    ll r = 0, m = 1;
    for (int i = 0; i < k; i++) {
        ll r2, m2;
        scanf("%lld %lld", &r2, &m2);
        ll g = extGcd(m, m2);
        ll diff = r2 - r;
        if (diff % g != 0) { printf("-1\n"); return 0; }
        ll mod = m2 / g;
        ll t = ((diff / g) % mod) * (coef % mod) % mod;
        if (t < 0) t += mod;
        ll newM = m / g * m2;
        r = (r + m * t) % newM;
        m = newM;
    }
    printf("%lld\n", r);
    return 0;
}
